style:
.nc-home { margin-bottom: var(--margin-lg); }
.nc-home-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: var(--margin-md); }
.nc-home-title { margin: 0; }
.nc-home-dept { display: flex; align-items: center; gap: var(--margin-sm); }
.nc-home-grid { display: grid; grid-template-columns: 2fr 1fr; gap: var(--margin-md); }
@media (max-width: 768px) { .nc-home-grid { grid-template-columns: 1fr; } }
.nc-home-grid.nc-home-wide { grid-template-columns: 1fr; }
.nc-home-card { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--border-radius-md); padding: var(--padding-md); }
.nc-home-card-title { margin: 0 0 var(--margin-sm); }
.nc-home-table { width: 100%; border-collapse: collapse; }
.nc-home-table th, .nc-home-table td { text-align: left; padding: var(--padding-xs) var(--padding-sm); border-bottom: 1px solid var(--border-color); }
.nc-home-table a { color: var(--text-color); text-decoration: none; }
.nc-home-table a:focus, .nc-home-stage a:focus, .nc-home-more:focus { outline: 2px solid var(--primary); }
.nc-home-stage { display: flex; justify-content: space-between; padding: var(--padding-xs) 0; border-bottom: 1px solid var(--border-color); }
.nc-home-num { font-variant-numeric: tabular-nums; }
.nc-home-error { color: var(--red-600); margin-bottom: var(--margin-sm); }
.nc-home-note { margin: var(--margin-sm) 0 0; }

script:
(function () {
	const root = root_element;
	const q = (sel) => root.querySelector(sel);
	const esc = (v) => frappe.utils.escape_html(String(v == null ? "" : v));
	const fmt = (n) => new Intl.NumberFormat("vi-VN").format(n);
	const state = { department: "", data: null, all: false };
	const PILL = { "Chờ trưởng khoa duyệt": "orange", "Chờ hội đồng thẩm định": "orange", "Chờ ban hành": "blue" };

	q(".nc-home-title").textContent = __("Normcore home");
	q(".nc-home-dept-label").textContent = __("Filter by department");
	q("#nc-home-pending-title").textContent = __("Pending tasks");
	q("#nc-home-stages-title").textContent = __("Services by chain status");
	q(".nc-home-note").textContent = __("Each service is counted at the highest stage it has reached.");

	function showError(msg) {
		const el = q(".nc-home-error");
		el.hidden = !msg;
		el.innerHTML = msg
			? `${esc(msg)} <button type="button" class="btn btn-xs btn-default nc-home-retry">${esc(__("Retry"))}</button>`
			: "";
		const btn = el.querySelector(".nc-home-retry");
		if (btn) btn.addEventListener("click", load);
	}

	function date(iso) {
		const [y, m, d] = String(iso).slice(0, 10).split("-");
		return `${d}/${m}/${y}`;
	}

	function renderDepartments(departments) {
		const sel = q(".nc-home-dept-select");
		sel.innerHTML =
			`<option value="">${esc(__("All departments in scope"))}</option>` +
			departments
				.map((d) => `<option value="${esc(d.name)}">${esc(d.department_name || d.name)}</option>`)
				.join("");
		sel.value = state.department;
	}

	function renderPending(pending) {
		const body = q(".nc-home-pending-body");
		const items = pending.filter((p) => !state.department || !p.department || p.department === state.department);
		q("#nc-home-pending-title").textContent = `${__("Pending tasks")} (${items.length})`;
		if (!items.length) {
			body.innerHTML = `<p class="text-muted">${esc(__("You have no pending tasks. Tasks waiting for your approval will appear here."))}</p>`;
			if (frappe.model.can_read("NC Clinical Procedure")) {
				body.innerHTML += `<a class="btn btn-sm btn-default" href="/app/nc-clinical-procedure">${esc(__("Open procedure list"))}</a>`;
			}
			return;
		}
		const shown = state.all ? items : items.slice(0, 10);
		const rows = shown
			.map(
				(p) => `<tr>
				<td><a href="${esc(p.route)}">${esc(p.task)}</a></td>
				<td><a href="${esc(p.route)}">${esc(p.title)}</a><div class="text-muted small">${esc(p.name)}</div></td>
				<td><span class="indicator-pill ${PILL[p.state] || "gray"}">${esc(p.state)}</span></td>
				<td>${esc(date(p.since))}${p.overdue ? ` <span class="indicator-pill red">${esc(__("Overdue"))}</span>` : ""}</td>
			</tr>`
			)
			.join("");
		body.innerHTML = `<table class="nc-home-table"><thead><tr>
			<th>${esc(__("Task"))}</th><th>${esc(__("Record"))}</th><th>${esc(__("Status"))}</th><th>${esc(__("Waiting since"))}</th>
			</tr></thead><tbody>${rows}</tbody></table>`;
		if (items.length > shown.length) {
			const more = document.createElement("button");
			more.type = "button";
			more.className = "btn btn-sm btn-default nc-home-more";
			more.textContent = `${__("View all")} (${items.length})`;
			more.addEventListener("click", () => {
				state.all = true;
				renderPending(pending);
			});
			body.appendChild(more);
		}
	}

	function renderStages(stages) {
		const card = q(".nc-home-stages");
		card.hidden = !stages.length;
		q(".nc-home-grid").classList.toggle("nc-home-wide", !stages.length);
		const body = q(".nc-home-stages-body");
		body.innerHTML = stages
			.map((s) => {
				let value;
				if (s.no_permission) {
					value = `<span class="text-muted">${esc(__("No permission to view"))}</span>`;
				} else {
					const dept = state.department ? `&nc_department=${encodeURIComponent(state.department)}` : "";
					const href = `/app/nc-technical-service?nc_chain_stage=${encodeURIComponent(s.stage)}${dept}`;
					value = `<a class="nc-home-num" href="${href}">${esc(fmt(s.count))}</a>`;
					if (s.assumption) value += ` <span class="indicator-pill yellow">${esc(__("Assumption — pending confirmation"))}</span>`;
				}
				return `<div class="nc-home-stage"><span>${esc(s.label)}</span><span>${value}</span></div>`;
			})
			.join("");
		if (stages.length && stages.every((s) => s.count === 0)) {
			body.innerHTML += `<p class="text-muted">${esc(__("There are no technical services yet."))} <a href="/app/nc-technical-service">${esc(__("Open service list"))}</a></p>`;
		}
	}

	function load() {
		root.querySelector(".nc-home-pending-body").innerHTML = `<p class="text-muted">${esc(__("Loading…"))}</p>`;
		frappe
			.xcall("normcore.api.home.get_home", { department: state.department || null })
			.then((data) => {
				showError("");
				state.data = data;
				renderDepartments(data.departments);
				renderPending(data.pending);
				renderStages(data.stages);
			})
			.catch((err) => {
				const msg = err && err.message ? String(err.message) : "";
				if (state.department && /phạm vi|scope/i.test(msg)) {
					state.department = "";
					showError(__("This department is outside your scope"));
					return load();
				}
				showError(__("Could not load the home page. Try again."));
			});
	}

	q(".nc-home-dept-select").addEventListener("change", (ev) => {
		state.department = ev.target.value;
		load();
	});
	frappe.realtime.on("notification", load);
	$(document).on("page-change", () => {
		if (root.isConnected) load();
	});
	load();
})();
